31	    @Mapping(target = "locality",
32	        expression = "java(org.springframework.samples.petclinic.util.CustomerCodes.regionOf(owner.getCustomerCode()))")
33	    @Mapping(target = "timezone",
34	        expression = "java(org.springframework.samples.petclinic.util.Localities.timezoneFor(org.springframework.samples.petclinic.util.CustomerCodes.regionOf(owner.getCustomerCode())))")
35	    @Mapping(target = "contactPreference",
36	        expression = "java(owner.getEmail() != null ? \"EMAIL\" : \"PHONE\")")
37	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
38	    @Mapping(target = "checkDigit",
39	        expression = "java(org.springframework.samples.petclinic.util.CheckDigits.luhn(owner.getCustomerCode()))")
40	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
41	    @Mapping(target = "possibleDuplicate", expression = "java(owner.getPossibleDuplicateOf() != null)")
42	    @Mapping(target = "telephoneDisplay",
43	        expression = "java(org.springframework.samples.petclinic.util.TelephoneFormatter.toDisplay(owner.getTelephone()))")
44	    OwnerDto toOwnerDto(Owner owner);
45	
46	    /** Age band derived from birthDate against registrationDate: MINOR (under 18), ADULT (18-64) or SENIOR (65+); null when birthDate is absent. */
47	    default String ageBand(Owner owner) {
48	        java.time.LocalDate birthDate = owner.getBirthDate();
49	        if (birthDate == null || owner.getRegistrationDate() == null) {
50	            return null;
51	        }
52	        int age = java.time.Period.between(birthDate, owner.getRegistrationDate()).getYears();
53	        if (age < 18) {
54	            return "MINOR";
55	        }
56	        return age < 65 ? "ADULT" : "SENIOR";
57	    }
58	
59	    /** The single duplicate-detection key: normalizedTelephone + '|' + (email or empty) + '|' + (householdId or empty). */
60	    default String identityKey(Owner owner) {
61	        return orEmpty(owner.getTelephone()) + '|' + orEmpty(owner.getEmail()) + '|' + orEmpty(owner.getHouseholdId());
62	    }
63	
64	    default String orEmpty(String value) {
65	        return value == null ? "" : value;
66	    }
67	
68	    /** Membership points: +2 for an email, +1 when namesakeCount is 0, +2 for a household of 3 or more, +3 for tenure over 365 days. */
69	    default int membershipPoints(Owner owner) {
70	        int points = 0;
71	        if (owner.getEmail() != null) {
72	            points += 2;
73	        }
74	        if (Integer.valueOf(0).equals(owner.getNamesakeCount())) {
75	            points += 1;
76	        }
77	        if (owner.getHouseholdMemberCount() != null && owner.getHouseholdMemberCount() >= 3) {
78	            points += 2;
79	        }
80	        if (tenureFiscalYears(owner) >= 1) {
81	            points += 3;
82	        }
83	        return points;
84	    }
